import React from 'react';
// import { useParams } from 'react-router-dom';
import ProductCard from '../components/ui/ProductCard';

function ProductDetailPage() {
  // const { id } = useParams(); // Nếu muốn fetch data theo id

  // Dữ liệu sản phẩm mẫu (thực tế sẽ fetch theo ID)
  const product = {
    title: 'Áo polo nam POHTK404',
    price: 379000,
    color: 'Đen',
    images: ['image-27-1.jpg', 'image-27-2.jpg', 'image-27-3.jpg'],
    description: [
      'Chất liệu: Poly co giãn thoáng mát',
      'Phom dáng: Regular Fit',
      'Kiểu dáng: Cổ bẻ 2 nút',
      'Phù hợp: Đi làm, đi chơi, dạo phố',
    ],
  };

  const hotProducts = [
    { id: 1, title: 'Áo polo nam POHTK401', price: 479000, imageUrl: 'image-27-1.jpg' },
    { id: 2, title: 'Áo polo nam POHTK402', price: 479000, imageUrl: 'image-27-5.jpg' },
    { id: 3, title: 'Áo polo nam POHTK403', price: 479000, imageUrl: 'image-27-3.jpg' },
    { id: 4, title: 'Áo polo nam POHTK405', price: 479000, imageUrl: 'image-27-4.jpg' },
  ];

  return (
    <div className="thuong-container">
      <section className="thuong-product-detail">
        <div className="thuong-images">
          {/* Ảnh chính */}
          <img
            src={`/assets/images/${product.images[0]}`}
            className="thuong-main-img"
            alt={product.title}
          />
          {/* Ảnh thumbnail */}
          <div className="thuong-thumb-list">
            {product.images.map((img, index) => (
              <img key={index} src={`/assets/images/${img}`} alt={`thumb-${index}`} />
            ))}
          </div>
        </div>

        <div className="thuong-info">
          <h1>{product.title}</h1>
          <div className="thuong-price">{new Intl.NumberFormat('vi-VN').format(product.price)}₫</div>

          <div className="thuong-color"><span>Màu sắc:</span> {product.color}</div>

          <div className="thuong-size">
            <span>Chọn cỡ:</span>
            {['S', 'M', 'L', 'XL'].map((size) => (
              <button key={size}>{size}</button>
            ))}
          </div>

          <div className="thuong-quantity">
            <span>Số lượng: </span>
            <input type="number" min="1" defaultValue="1" />
          </div>

          <button className="thuong-add-cart">Thêm vào giỏ hàng</button>

          <div className="thuong-description">
            <p><b>Mô tả:</b></p>
            <ul>
              {product.description.map((desc, index) => (
                <li key={index}>{desc}</li>
              ))}
            </ul>
          </div>
        </div>
      </section>

      {/* Sản phẩm bán chạy */}
      <h2 className="thuong-hot-title">SẢN PHẨM BÁN CHẠY</h2>
      <div className="thuong-hot-products">
        {hotProducts.map(prod => (
          <ProductCard key={prod.id} data={prod} />
        ))}
      </div>
    </div>
  );
}

export default ProductDetailPage;
